const set = (id,title,icon,section,source) => ({
  id,title,icon,section,
  questions:source.trim().split('\n').map(line=>{
    const [id,question,answer,sinhala,cue,followUp,followAnswer]=line.split('|');
    return {id,question,answer,sinhala,cue,followUp,followAnswer};
  }),
});

